import Base from '../layouts/Base.astro';

const groups = [
  {
    name: 'Tabs',
    rows: [
      ['⌘T', 'New terminal tab'], ['⌘⇧B', 'New browser tab'], ['⌘W', 'Close active tab'],
      ['⌘⇧]', 'Next terminal tab'], ['⌘⇧[', 'Previous terminal tab'], ['⌃Tab / ⌃⇧Tab', 'cycle tabs'],
      ['⌃1..9', 'Select terminal tab N'], ['⌘1..9', 'Select workspace N'],
    ],
  },
  {
    name: 'Terminal panes',
    rows: [
      ['⌘D', 'Split terminal right'], ['⌘⇧D', 'Split terminal down'], ['⌘⌥D', 'Close split view'],
      ['⌘]', 'Focus next pane'], ['⌘[', 'Focus previous pane'], ['⌘F', 'Find in terminal'],
    ],
  },
  {
    name: 'Global',
    rows: [
      ['⌘K (alias ⌘P)', 'Command palette'], ['⌘B', 'Toggle sidebar'], ['⌘,', 'Toggle settings'],
      ['⌘=', 'Zoom in'], ['⌘-', 'Zoom out'], ['⌘0', 'Reset zoom'],
    ],
  },
];
---

<Base title="Shortcuts">
  <h1>Shortcuts</h1>
  <p>These match the in-app bindings defined in ui/src/lib/shortcuts.ts.</p>
  {groups.map((group) => (
    <section>
      <h2>{group.name}</h2>
      <table>
        <thead><tr><th>Keys</th><th>Action</th></tr></thead>
        <tbody>
          {group.rows.map(([keys, action]) => <tr><td><kbd>{keys}</kbd></td><td>{action}</td></tr>)}
        </tbody>
      </table>
    </section>
  ))}
</Base>

